import{_ as o,o as r,c as s,j as e,a}from"./chunks/framework.QCr1ZR1X.js";const c=JSON.parse('{"title":"思维导图-第3章-工业互联网网络互通","description":"","frontmatter":{},"headers":[],"relativePath":"mindmap/思维导图-第3章-工业互联网网络互通.md","filePath":"mindmap/思维导图-第3章-工业互联网网络互通.md","lastUpdated":1786967935000}'),d={name:"mindmap/思维导图-第3章-工业互联网网络互通.md"};function i(n,t,C,P,_,b){return r(),s("div",null,[...t[0]||(t[0]=[e("h1",{id:"思维导图-第3章-工业互联网网络互通",tabindex:"-1"},[a("思维导图-第3章-工业互联网网络互通 "),e("a",{class:"header-anchor",href:"#思维导图-第3章-工业互联网网络互通","aria-label":'Permalink to "思维导图-第3章-工业互联网网络互通"'},"​")],-1),e("div",{class:"mermaid"},'# 第3章 工业互联网网络互通 — 思维导图 ## 3.1 车间里的"巴别塔"——设备怎么对话 ### 场景导入：焊装车间的四种语言 - 七种设备至少四种协议 - FANUC机器人（私有协议） - SIEMENS PLC（ProfiNet） - ABB焊接机（EtherNet/IP） - KEYENCE视觉（EtherCAT） - BALLUFF RFID（Modbus RTU） ### 三种解决思路 - 统一协议：全厂统一（成本极高，现实中无法完全实现） - 协议转换网关：配翻译 - 通用中间层（OPC UA） ### ISA-95：工厂通信的五层地图 - L0 现场设备层：传感器/执行器（"现在温度75.3℃"） - L1 控制层：PLC/DCS/CNC（"如果>80℃，关闭加热器"） - L2 监控层：SCADA/HMI（"3号线所有设备状态"） - L3 制造运营层：MES/WMS/QMS（"这批订单做到哪了？"） - L4 业务层：ERP/PLM/SCM（"这个月赚了还是亏了？"） - ISA-95与IIRA对应关系 - L0-L1 → 边缘层 - L2-L3 → 平台层+应用层 - L4 → 业务层 ## 3.2 动手实践：搭台唱戏——安装Node-RED ### 实践任务 - 安装Node-RED（bash一键安装脚本） - 启动Node-RED并设为开机自启 - node-red-start - systemctl enable nodered - 浏览器访问Web界面 - http://虚拟机IP:1880 - 安装Modbus节点 - node-red-contrib-modbus - 用Comment节点关联ISA-95模型 - L0-L4五层标注 ## 3.3 六大协议"华山论剑"——现场总线与外部网络 ### 六大协议一览 - ProfiNet / Profibus（西门子） - 紫色线=Profibus（RS-485老款） - 绿色工业网线=ProfiNet（以太网新款） - 三种通信等级：标准TCP/IP、RT实时、IRT等时同步 - EtherCAT（倍福） - 飞读飞写（Processing on the Fly） - 物理层和普通以太网完全一样（成本低） - 运动控制和高速采集标杆 - CC-Link / CC-Link IE（三菱） - 日系工厂标配 - 环形冗余，断线不中断 - Modbus RTU/TCP（施耐德，1979年Modicon设计） - 完全免费开放 - 四种寄存器 - 线圈（Coil，1bit R/W） - 离散输入（1bit RO） - 保持寄存器（16bit R/W） - 输入寄存器（16bit RO） - 五种常用功能码 - FC01读线圈、FC02读离散输入、FC03读保持寄存器、FC04读输入寄存器、FC06写单寄存器 - 最大局限：从站不能主动"喊"主站 - Powerlink（贝加莱/ABB） - 标准硬件+开源协议栈 - DeviceNet / EtherNet/IP（罗克韦尔/ODVA） - 基于CAN/CIP协议 - 北美市场 ### 拓展：传输介质与连接器 - RJ45工业级（金属加固卡扣） - DB9串口（RS-485/Profibus） - M12圆形连接器（IP67防尘防水） - 屏蔽双绞线STP（抗电磁干扰） - 工业交换机（金属外壳、导轨安装、IP40、宽温） ### 拓展：工厂外部网络 - 专线/VPN（MPLS-VPN/加密隧道） - 4G/5G无线回传 - 5G三大特性 - eMBB：大带宽（高清视频巡检） - uRLLC：超可靠低时延（远程控制） - mMTC：海量连接（油田设备） ## 3.4 动手实践：模拟一次设备对话——ModbusTCP通信实战 ### 实践任务 - 搭建ModbusTCP从站 - Modbus Server节点 + Response节点 - 模拟温湿度传感器 - 端口8502（避免权限问题） - 温度/湿度/状态三个寄存器 - 搭建ModbusTCP主站 - Modbus Read节点（FC03读保持寄存器） - 每2秒轮询 - Debug节点输出 - 用QModMaster外部调试工具直连从站读写寄存器 - 制造并排查通信故障 - 修改端口→Connection refused - 改回正确端口→恢复 - 故障排查顺序：网线→IP→端口→从站ID→防火墙 ## 🎯 课程思政 - 每一行协议都是承诺——工业通信中的工匠精神 - 2015年乌克兰电网遭网络攻击（IEC 104协议漏洞），22.5万用户断电 - 工业协议对"确定性"和"可靠性"要求远高于消费协议 - 一个字节出错可能导致生产线停转、设备损毁甚至人员伤亡',-1)])])}const L=o(d,[["render",i]]);export{c as __pageData,L as default};
